from solution import find_length


def test_issue_example_given():
    """Example asserts find_length("11000010001", 11) == 6."""
    assert find_length("11000010001", 11) == 6  # 7-1=6


def test_issue_all_zeros():
    """Maximum difference of zeros and ones in any sub-string for all zeros."""
    assert find_length("0000", 4) == 4  # 4-0=4


def test_issue_single_zero():
    """Maximum difference of zeros and ones in any sub-string for single zero."""
    assert find_length("0", 1) == 1  # 1-0=1


def test_issue_01_best_is_single_zero():
    """Maximum difference of zeros and ones in any sub-string for "01"."""
    assert find_length("01", 2) == 1  # 1-0=1


def test_issue_10_best_is_single_zero():
    """Maximum difference of zeros and ones in any sub-string for "10"."""
    assert find_length("10", 2) == 1  # 1-0=1


def test_issue_zeros_then_ones():
    """Maximum difference of zeros and ones in any sub-string for "000111"."""
    assert find_length("000111", 6) == 3  # 3-0=3


def test_issue_ones_then_zeros():
    """Maximum difference of zeros and ones in any sub-string for "111000"."""
    assert find_length("111000", 6) == 3  # 3-0=3


def test_issue_middle_best():
    """Maximum difference of zeros and ones in any sub-string is interior."""
    assert find_length("111000111", 9) == 3  # 3-0=3


def test_issue_longer_mixed():
    """Maximum difference of zeros and ones in any sub-string for "01000010"."""
    assert find_length("01000010", 8) == 4  # 6-2=4


def test_issue_all_ones():
    """Maximum difference of zeros and ones in any sub-string for all ones."""
    assert find_length("111", 3) == -1  # 0-1=-1


def test_contract_returns_int():
    """Function find_length(string, n) returns maximum difference as int."""
    assert isinstance(find_length("0000", 4), int)  # expected literal 4 is int: 4-0=4


def test_contract_empty_without_error():
    """Function find_length(string, n) handles empty input without error."""
    assert isinstance(find_length("", 0), int)  # empty has no sub-string, still int
